package io.coolbox.ensemble;
import io.coolbox.internal.*;import com.sun.jna.ptr.IntByReference;
/** Classification ensemble (Python: {@code tree_ensemble.BoostTreeClassifier}). */
public final class BoostTreeClassifier extends NativeHandle {private static final EnsembleNative N=EnsembleNative.INSTANCE;private int features;public BoostTreeClassifier(){this(new BoostTreeParameters());}public BoostTreeClassifier(BoostTreeParameters p){super(create(p),N::coolbox_boost_tree_classifier_free);}private static com.sun.jna.Pointer create(BoostTreeParameters p){ErrorBuffer e=new ErrorBuffer();return e.check(N.coolbox_boost_tree_classifier_new(p.numEstimators,p.learningRate,p.maxDepth,e.pointer(),e.capacity()));}public BoostTreeClassifier fit(double[][] x,int[] y){features=Matrices.columns(x);if(y.length!=x.length)throw new IllegalArgumentException("label count differs from rows");ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_classifier_fit(handle(),Matrices.flatten(x),x.length,features,y,e.pointer(),e.capacity()));return this;}public int predict(double[] sample){IntByReference o=new IntByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_classifier_predict(handle(),sample,sample.length,o,e.pointer(),e.capacity()));return o.getValue();}public double[] predictProba(double[] sample){int n=classes().length;double[] p=new double[n];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_boost_tree_classifier_predict_proba(handle(),sample,sample.length,p,n,e.pointer(),e.capacity()));return p;}public int[] classes(){ErrorBuffer e=new ErrorBuffer();int n=(int)N.coolbox_boost_tree_classifier_class_count(handle(),e.pointer(),e.capacity());e.throwIfSet();int[] a=new int[n];e.check(N.coolbox_boost_tree_classifier_copy_classes(handle(),a,n,e.pointer(),e.capacity()));return a;}}
